ROWS: dict[int, str] = {}
CASES: list[dict] = []


def parse_cards() -> list[dict]:
    chapters = []
    for c, title in enumerate(TITLES, 1):
        cards = []
        for n, row in enumerate(CARD_ROWS[c].strip().splitlines(), 1):
            name, expression, symbols, conditions, units, pitfall, hint = row.split("|")
            cards.append(dict(id=f"finance-{c:02d}-formula-{n}", name=name, title=name,
                expression=expression, symbols=symbols, conditions=conditions,
                units=units, pitfalls=[pitfall], hint=hint))
        chapters.append(dict(chapter_no=c, title=title, world="finance", cards=cards,
            formulas=cards,
            formula_texts=[f"{x['title']}：{x['expression']}。{x['symbols']}；适用：{x['conditions']}" for x in cards]))
    return chapters


def explanation_from_analysis(a: dict) -> str:
    parts = [f"【考点】{a['position']}", f"【原理】{a['principle']}"]
    if a["formulas"]:
        parts.append("【公式与条件】" + "\n".join(a["formulas"]))
    if a["steps"]:
        parts.append("【推导】" + "\n".join(f"{i}. {s}" for i, s in enumerate(a["steps"], 1)))
    if a["option_analysis"]:
        parts.append("【逐项分析】" + "\n".join(f"{k}：{v}" for k, v in a["option_analysis"].items()))
    parts.extend(["【单位与精度】" + a["units"], "【易错点】" + "；".join(a["pitfalls"]), "【记忆提示】" + a["memory"]])
    return "\n\n".join(parts)


def objectives(chapters: list[dict]) -> list[dict]:
    out = []
    for c in range(1, 21):
        rows = ROWS[c].strip().splitlines()
        if len(rows) != 20:
            raise ValueError(f"第{c}章应有20道客观题，实际{len(rows)}")
        for n, row in enumerate(rows, 1):
            topic, stem, right, choices, why, formula, units, memory = row.split("|")
            entries = [v.split("~", 1) for v in choices.split("/")]
            if len(entries) != 4 or any(len(x) != 2 for x in entries):
                raise ValueError((c, n, "每个选项必须有独立判断理由"))
            qid = f"orig-cg-{c:02d}-{n:02d}"
            tagged = [(i, *e) for i, e in enumerate(entries, 1)]
            random.Random(qid).shuffle(tagged)
            options, option_analysis = {}, {}
            answer = ""
            for letter, (idx, text, reason) in zip("ABCD", tagged):
                correct = str(idx) in right
                options[letter] = text
                option_analysis[letter] = f"{'正确' if correct else '错误'}。{reason}"
                if correct:
                    answer += letter
            pitfalls = [r for i, (_, r) in enumerate(entries, 1) if str(i) not in right]
            a = dict(position=f"第{c}章·{topic}", principle=why,
                formulas=[formula] if formula != "—" else [],
                steps=[s for s in why.split("；") if s], option_analysis=option_analysis,
                units=units, pitfalls=pitfalls, memory=memory)
            out.append(dict(id=qid, book_id="cg_original_v02", world="finance",
                chapter_no=c, chapter=f"第{c}章 {TITLES[c-1]}", num=str(n),
                type="单选题" if n <= 14 else "多选题", stem=stem,
                options=options, answer=answer, explanation=explanation_from_analysis(a),
                difficulty=2 if n <= 10 else 3, source_id="project_finance_original",
                source_ref={"kind": "project_original", "source_id": "project_finance_original",
                            "source_title": SOURCES["project_finance_original"]["title"],
                            "chapter_no": c, "topic": topic, "revision": REVISION},
                tags=["原创", "CPA", topic], analysis=a, subquestions=[], numeric_checks=[],
                authorship={"kind": "project_original", "revision": REVISION, "review_status": "candidate"}))
    return out


def check(key: str, label: str, value: str, unit: str, decimals: int | None = 2, exact: bool = False) -> dict:
    return dict(key=key, label=label, value=value, unit=unit, decimals=decimals, exact=exact)


def sub(n: int, prompt: str, reference: str, checks: list[dict], process: list[str]) -> dict:
    return dict(id=str(n), prompt=prompt, reference=reference,
        checks=[x["key"] for x in checks], process_checklist=process, _checks=checks)


def case(c: int, n: int, topic: str, stem: str, subs: list[dict], principle: str,
         formulas: list[str], pitfall: str, memory: str, parameters: dict | None = None) -> None:
    qid = f"orig-cg-{c:02d}-case-{n}"
    checks = [x for s in subs for x in s.pop("_checks")]
    a = dict(position=f"第{c}章·{topic}", principle=principle, formulas=formulas,
        steps=[f"第{s['id']}问：{s['reference']}" for s in subs], option_analysis={},
        units="各小问明确标注单位；保留2位小数的数值按最后一位半个单位核对，精确数量严格核对。百分数输入采用百分数数值，如10%填10。过程须逐问自评。",
        pitfalls=[pitfall], memory=memory)
    answer = "\n\n".join(f"（{s['id']}）{s['reference']}" for s in subs)
    CASES.append(dict(id=qid, book_id="cg_original_v02", world="finance",
        chapter_no=c, chapter=f"第{c}章 {TITLES[c-1]}", num=f"案例{n}",
        type="计算分析题", stem=stem + "\n" + "\n".join(f"（{s['id']}）{s['prompt']}" for s in subs),
        options={}, answer=answer, explanation=explanation_from_analysis(a), difficulty=3,
        source_id="project_finance_original", source_ref={"kind": "project_original", "source_id": "project_finance_original",
                                                       "source_title": SOURCES["project_finance_original"]["title"],
                                                       "chapter_no": c, "topic": topic, "revision": REVISION,
                                                       "parameters": parameters or {}},
        tags=["原创", "CPA", "主观Boss", topic], analysis=a, subquestions=subs, numeric_checks=checks,
        authorship={"kind": "project_original", "revision": REVISION, "review_status": "candidate"}))


def validate(questions: list[dict]) -> dict:
    ids, stems, topics = set(), set(), set()
    numeric_count = 0
    for q in questions:
        assert q["id"] not in ids, q["id"]
        ids.add(q["id"])
        normalized = re.sub(r"\s+", "", q["stem"])
        assert normalized not in stems, q["id"]
        stems.add(normalized)
        topic = (q["chapter_no"], q["analysis"]["position"])
        assert topic not in topics, (q["id"], topic)
        topics.add(topic)
        if q["options"]:
            assert set(q["options"]) == set("ABCD"), q["id"]
            assert len(set(q["options"].values())) == 4, q["id"]
            assert 1 == len(q["answer"]) if q["type"] == "单选题" else 2 <= len(q["answer"]) <= 4, q["id"]
            for k, v in q["analysis"]["option_analysis"].items():
                assert v.startswith("正确。" if k in q["answer"] else "错误。"), q["id"]
        else:
            assert len(q["subquestions"]) >= 2, q["id"]
            keys = [x["key"] for x in q["numeric_checks"]]
            assert len(set(keys)) == len(keys), q["id"]
            assert set(keys) == {k for s in q["subquestions"] for k in s["checks"]}, q["id"]
            for s in q["subquestions"]:
                assert s["reference"] and s["process_checklist"], q["id"]
            for x in q["numeric_checks"]:
                assert Decimal(x["value"]).is_finite(), q["id"]
                assert x["unit"] in {"元", "万元", "%", "小数", "件", "年", "无单位"}, q["id"]
                assert x["decimals"] is None or x["decimals"] >= 0, q["id"]
            numeric_count += len(keys)
        a = q["analysis"]
        assert set(a) == {"position", "principle", "formulas", "steps", "option_analysis", "units", "pitfalls", "memory"}, q["id"]
        assert a["principle"] and a["units"] and a["pitfalls"] and a["memory"], q["id"]
        assert q["explanation"] == explanation_from_analysis(a), q["id"]
    coverage = []
    for c in range(1, 21):
        counts = Counter(q["type"] for q in questions if q["chapter_no"] == c)
        assert counts == {"单选题": 14, "多选题": 6, "计算分析题": 2}, (c, counts)
        coverage.append(dict(chapter_no=c, title=TITLES[c-1], singles=14, multiples=6, cases=2,
                             distinct_positions=22))
    assert len(questions) == 440
    return dict(question_count=440, objective_count=400, case_count=40,
        single_count=280, multiple_count=120, numeric_check_count=numeric_count,
        unique_stem_count=len(stems), distinct_positions=len(topics), chapters=coverage)


def atomic_json(path: Path, obj: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    temp.replace(path)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--verified", action="store_true", help="独立复算测试通过后标记为内部已复核")
    args = parser.parse_args()
    chapters = parse_cards()
    questions = objectives(chapters) + CASES
    coverage = validate(questions)
    case_evidence = []
    objective_evidence = []
    if args.verified:
        # 临时输出候选数据供独立测试读取；测试失败时保留candidate，不冒充核验成功。
        candidate = {"schema_version": 2, "id": "xiaoyuan-original-finance-v02", "revision": REVISION,
                     "questions": {q["id"]: q for q in questions}}
        atomic_json(BANK_PATH, candidate)
        subprocess.run([sys.executable, "-m", "unittest", "discover", "-s", str(ROOT / "tests"),
                        "-p", "test_finance_original.py", "-v"], cwd=ROOT, check=True)
        evidence = json.loads(AUDIT_PATH.read_text(encoding="utf-8"))
        case_evidence = evidence["case_recalculations"]
        objective_evidence = evidence["objective_recalculations"]
        for q in questions:
            q["authorship"]["review_status"] = "verified_internal"
    canonical = json.dumps(questions, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    fingerprint = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
    status = "verified_internal" if args.verified else "candidate"
    bank = dict(schema_version=2, id="xiaoyuan-original-finance-v02", revision=REVISION,
        review_status=status, authored_at=CHECKED, note=SOURCES["project_finance_original"]["note"],
        sources=SOURCES, questions={q["id"]: q for q in questions}, fingerprint=fingerprint,
        coverage=coverage)
    knowledge = dict(schema_version=1, revision=REVISION, world="finance", sources=SOURCES,
        note="原创公式卡；章节编号与2026财管20章对应。公式须结合卡片条件使用。",
        chapters=chapters)
    audit = dict(schema_version=1, checked_at=CHECKED, review_status=status, fingerprint=fingerprint,
        **coverage, formula_card_count=sum(len(c["cards"]) for c in chapters),
        checks={"schema": "passed", "per_chapter_distribution": "passed", "unique_stems": "passed",
                "option_labels_match_answers": "passed", "individual_option_rationale": "passed",
                "case_check_reference_integrity": "passed", "independent_case_recalculation": "passed" if args.verified else "not_run",
                "independent_numeric_objective_models": "passed" if args.verified else "not_run"},
        case_recalculations=case_evidence,
        independent_case_check_count=sum(len(item["values"]) for item in case_evidence),
        objective_recalculations=objective_evidence,
        independent_objective_check_count=len(objective_evidence),
        editorial_review={"status": "reviewed_internal" if args.verified else "candidate",
                          "scope": "20章400道客观题题干与已标记正确选项逐章核对；四个选项的唯一性与判断理由结构自动检查；40案例168数值及170数值客观题独立复算",
                          "clarifications": ["删除两处对上一题的依赖表述，补充同标的同到期期权、杠杆正分母与项目同服务条件",
                                             "补充16道题的过短或重复选项理由；修复跨章重复题干；检查原创项目出处"]},
        limitations=["内部原创内容复核；未取得外部专业编辑或CPA教师签审。", "仅本轮新增440题；旧264题与私人题库由整合流程单独维护。"],
        outputs={"bank": str(BANK_PATH), "knowledge": str(KNOWLEDGE_PATH)},
        reproducible_command="python tools/create_finance_original_bank.py --verified")
    atomic_json(BANK_PATH, bank)
    atomic_json(KNOWLEDGE_PATH, knowledge)
    atomic_json(AUDIT_PATH, audit)
    sys.stdout.write(json.dumps({"题数": 440, "案例数": 40, "复核状态": status, "数值检查数": coverage["numeric_check_count"], "指纹": fingerprint}, ensure_ascii=False) + "\n")


